CREATE INDEX "store_orderline_order_id_5a82cf64" ON "store_orderline" ("order_id");
CREATE INDEX "store_orderline_product_id_6da908ca" ON "store_orderline" ("product_id");
CREATE VIEW "store_open_orders" AS SELECT "id", "customer_id", "created_at" FROM "store_order" WHERE "status" = 'open';
